// A generic memoize wrapper
function memoize(fn) {
  const cache = {};

  return function(...args) {
    // Create a simple string key from arguments
    const key = JSON.stringify(args);

    // Check if we already calculated this
    if (cache[key]) {
      console.log('Fetching from cache:', key);
      return cache[key];
    }

    // Otherwise, calculate and store it
    console.log('Calculating result for:', key);
    const result = fn.apply(this, args);
    cache[key] = result;
    return result;
  };
}

// An expensive function
const slowSquare = (n) => {
  // Imagine this takes 2 seconds
  return n * n;
};

const memoizedSquare = memoize(slowSquare);

console.log(memoizedSquare(10)); // Calculating result for: [10] -> 100
console.log(memoizedSquare(10)); // Fetching from cache: [10] -> 100
console.log(memoizedSquare(5));  // Calculating result for: [5] -> 25
console.log(memoizedSquare(5));  // Fetching from cache: [5] -> 25
